package hr.hrg.fsmeta;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * The Java reader against the shared v2 vectors — {@code conformance/fsmeta-vectors-v2.json}, generated by
 * the Zig reference and asserted by the Bun reader too.
 *
 * <p>This is the format's gate: every case materialises a real {@code <case>/.fs-meta/} trio, the reader
 * runs over the files, and the verdict must be the one the reference recorded. The cases include two whose
 * point is the order of § 8's checks ({@code meta-hash-mismatch} before any entry, and {@code invalid-flags}
 * last), so a reader that reaches the right answer for the wrong reason still fails here.</p>
 *
 * <p>The older {@code conformance/fsmeta-vectors.json} describes the pre-v2 entry layout and is not asserted
 * by this test. The v2 file is generated by the reference writer; the vectors are not edited to match this
 * reader.</p>
 */
class FsMetaConformanceTest {

    private static final Path VECTORS = locateVectors();

    /**
     * Finds the vector file relative to the module directory. Surefire runs with the module as its working
     * directory, but a run from the reactor root or an IDE must find the same file, so the parents are
     * walked as a fallback.
     */
    private static Path locateVectors() {
        Path working = Path.of("").toAbsolutePath();
        List<Path> candidates = new ArrayList<>();
        candidates.add(Path.of("conformance", "fsmeta-vectors-v2.json"));
        candidates.add(Path.of("fs-meta", "conformance", "fsmeta-vectors-v2.json"));
        for (Path directory = working; directory != null; directory = directory.getParent()) {
            candidates.add(directory.resolve("conformance").resolve("fsmeta-vectors-v2.json"));
        }
        for (Path candidate : candidates) {
            if (Files.isRegularFile(candidate)) {
                return candidate;
            }
        }
        throw new IllegalStateException("conformance/fsmeta-vectors-v2.json not found from " + working
                + "; looked at " + candidates);
    }

    @Test
    void everyVectorCaseReachesTheVerdictItRecords(@TempDir Path temporary) throws IOException {
        List<Object> cases = asList(vectors().get("cases"));
        Assertions.assertEquals(14, cases.size(), "the v2 vector file carries the fourteen conformance cases");

        int checked = 0;
        for (Object element : cases) {
            Map<String, Object> testCase = asMap(element);
            String name = text(testCase.get("name"));
            String expected = text(testCase.get("expect"));

            FsMetaLoad load = loadCase(testCase, temporary);
            Assertions.assertEquals(expected, load.verdict().wire(), "verdict for case '" + name + "'");
            if (expected.equals(FsMetaVerdict.OK.wire())) {
                Assertions.assertTrue(load.ok(), "case '" + name + "': " + load.describe());
                Assertions.assertNotNull(load.pair(), "case '" + name + "' must decode the entries and names");
                Assertions.assertEquals(load.config().countAsInt(), load.pair().size(),
                        "case '" + name + "' must decode one entry per document count");
            } else {
                Assertions.assertFalse(load.ok(), "case '" + name + "' must be unusable");
                Assertions.assertNull(load.pair(), "case '" + name + "' must not expose entries");
            }
            checked++;
        }
        Assertions.assertEquals(cases.size(), checked, "every case must be exercised");
    }

    @Test
    void theOkCaseDecodesTheEntriesAndNamesItPublishes(@TempDir Path temporary) throws IOException {
        FsMetaLoad load = loadCase(caseNamed("ok"), temporary);
        Assertions.assertEquals(FsMetaVerdict.OK, load.verdict(), load.describe());

        FsMetaPair pair = load.pair();
        Assertions.assertNotNull(pair);
        Assertions.assertEquals(List.of("a.txt", "src/b.java", "src/"), pair.names());

        FsMetaEntry file = pair.entry(0);
        Assertions.assertEquals(6L, file.sizeBytes());
        Assertions.assertEquals(0L, file.nameOffset());
        Assertions.assertEquals(5, file.nameLength());
        Assertions.assertEquals(0x0B, file.flags(), "CONTENT_KNOWN | REGULAR_FILE | HASH_LF");
        Assertions.assertEquals("e6d129338e065990", FsMetaHash.hex(file.contentHash()));
        Assertions.assertEquals("6a917dd1ac09c082", FsMetaHash.hex(file.nameHash()));

        // The engine orders the meta by (nameHash, name), so the directory entry is third, and its stored name
    // carries the trailing slash of § 4.
    FsMetaEntry directory = pair.entry(2);
        Assertions.assertTrue(directory.directory(), "flags 0x04 are IS_DIR");
        Assertions.assertEquals(0L, directory.sizeBytes());
        Assertions.assertEquals(6L, directory.nameOffset());
        Assertions.assertEquals(4, directory.nameLength());

        FsMetaEntry nested = pair.entry(1);
        Assertions.assertEquals(11L, nested.nameOffset());
        Assertions.assertEquals(10, nested.nameLength());
        Assertions.assertEquals("9c73c214947f2d69", FsMetaHash.hex(nested.contentHash()));
    }

    @Test
    void aDirectoryWhoseStoredNameCarriesTheSlashStillHashesWithoutIt() {
        // FORMAT.md § 3/§ 4 and the current Zig writer store a directory's line as `src/`, while its nameHash
        // and lookup name are `src`. The v2 vector predates that layout detail and stores `src` without the
        // slash, so the reader accepts both: it strips the slash only for a directory entry's hash check.
        List<String> names = List.of("a.txt", "src/", "src/b.java");
        byte[] txt = FsMetaCodec.encodeNames(names);
        List<FsMetaEntry> entries = List.of(
                new FsMetaEntry(1L, 6L, FsMetaHash.of(FsMetaHash.utf8("hello\n")),
                        FsMetaHash.ofName("a.txt"), 0L, 5, FsMetaFormat.fileFlags(true), 0L, 0L),
                new FsMetaEntry(2L, 0L, 0L, FsMetaHash.ofName("src"),
                        6L, 4, FsMetaFormat.directoryFlags(), 0L, 0L),
                new FsMetaEntry(3L, 11L, FsMetaHash.of(FsMetaHash.utf8("class B {}\n")),
                        FsMetaHash.ofName("src/b.java"), 11L, 10, FsMetaFormat.fileFlags(true), 0L, 0L));
        byte[] meta = FsMetaCodec.encodeEntries(entries);
        FsMetaConfig config = FsMetaConfig.forPublish(entries.size(), meta, txt, 1L,
                FsMetaHashMode.TEXT, "test/1", "", "", "");

        FsMetaValidation validation = FsMetaValidator.validate(meta, txt, config);
        Assertions.assertEquals(FsMetaVerdict.OK, validation.verdict(), validation.detail());
    }

    // ------------------------------------------------------------------ vector navigation

    /** Materialises {@code <tmp>/<case>/.fs-meta/} and reads it with the production reader. */
    private static FsMetaLoad loadCase(Map<String, Object> testCase, Path temporary) throws IOException {
        String name = text(testCase.get("name"));
        Path trio = temporary.resolve(name).resolve(FsMetaFormat.DIRECTORY_NAME);
        Files.createDirectories(trio);
        Files.write(trio.resolve(FsMetaFormat.META_FILE),
                HexFormat.of().parseHex(text(testCase.get("meta"))));
        Files.writeString(trio.resolve(FsMetaFormat.TXT_FILE), text(testCase.get("txt")),
                StandardCharsets.UTF_8);
        Files.writeString(trio.resolve(FsMetaFormat.JSON_FILE), text(testCase.get("json")),
                StandardCharsets.UTF_8);
        return FsMetaPair.load(trio);
    }

    private static Map<String, Object> vectors() throws IOException {
        return asMap(Json.parse(Files.readString(VECTORS, StandardCharsets.UTF_8)));
    }

    private static Map<String, Object> caseNamed(String name) throws IOException {
        for (Object element : asList(vectors().get("cases"))) {
            Map<String, Object> testCase = asMap(element);
            if (name.equals(text(testCase.get("name")))) {
                return testCase;
            }
        }
        throw new AssertionError("no vector case named '" + name + "'");
    }

    @SuppressWarnings("unchecked")
    private static Map<String, Object> asMap(Object value) {
        return (Map<String, Object>) value;
    }

    @SuppressWarnings("unchecked")
    private static List<Object> asList(Object value) {
        return (List<Object>) value;
    }

    private static String text(Object value) {
        return (String) value;
    }
}
